def verify_bitonic(arr):
    n = len(arr)
    if n <= 1:
        return True
    # Find increasing part
    inc_pos = -1
    for i in range(1, n):
        if arr[i] > arr[i-1]:
            inc_pos = i
        else:
            break
    # From inc_pos to end, must be decreasing
    for i in range(inc_pos + 1, n):
        if arr[i] > arr[i-1]:
            return False
    return True

