def solution(data: str) -> str:
    """
    Main solution function.
    Uses finding divisors and arranging them to minimize LCM insertions.
    """
    lines = data.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0].strip())
    test_cases = lines[1:t+1]

    result_lines = []
    primes = []

