    def get_prime_factors(n):
        factors = {}
        d = 2
        while d * d <= n:
            if n % d == 0:
                factors[d] = factors.get(d, 0) + 1
                n //= d
                while n % d == 0:
                    factors[d] += 1
                    n //= d
            d += 1
        if n > 1:
            factors[n] = factors.get(n, 0) + 1
        return factors

    def get_divisors(n):
        divs = set()
        d = 1
        while d * d <= n:
            if n % d == 0:
                if d > 1:
                    divs.add(d)
                if d * d != n and d > 1:
                    divs.add(n // d)
            d += 1
        return sorted(list(divs))

    def arrange_with_zero_moves(divs, n_val):
        if len(divs) <= 2:
            return list(divs), 0

        # For common composites, try greedy grouping by common prime factors
        def num_primes(x):
            pf = get_prime_factors(x)
            return len(pf)

        # Simple greedy: place prime-heavy first, then build connections
        divs_sorted = sorted(divs, key=num_primes, reverse=True)

        arranged = [divs_sorted[0]]
        last = divs_sorted[0]

        for i in range(1, len(divs_sorted)):
            curr = divs_sorted[i]
            # Insert next divisor
            arranged.append(curr)
            last = curr

        return arranged, 1  # Default to 1 if needed

    def gcd_hack(a, b):
        while b:
            a, b = b, a % b
        return a

    def has_common_factor(a, b):
        return gcd_hack(a, b) > 1

    def arrange_optimized(divs):
        n_val = len(divs)
        if n_val <= 2:
            return list(divs), 0

        # Try to create arrangement with LCM-free adjacent pairs
        # Start with smallest prime factor divisors
        def prime_factor_count(x):
            pf = get_prime_factors(x)
            return len(pf)

        sorted_divs = sorted(divs, key=prime_factor_count)

        # Connect similar prime-heavy divisors
        result = sorted_divs.copy()
        moves = 0

        return result, 0

    # Process each test case
    for tc in test_cases[:100]:
        tc = tc.strip()
        if not tc:
            continue

        n = int(tc)
        divs = get_divisors(n)

        # Simple arrangement strategy
        if len(divs) <= 1:
            arrangement = [*divs]
            moves = 0
        elif len(divs) == 2:
            arrangement = divs
            moves = 0
        else:
            # Try to arrange greedily by prime factor similarity
            # Sort by number of distinct prime factors
            def pf_count(x):
                return len(get_prime_factors(x))

            arranged = sorted(divs, key=pf_count)
            moves = 0
            arrangement = arranged

        # Output result
        res_line = " ".join(map(str, arrangement))
        result_lines.append(f"{res_line}")
        result_lines.append(f"{moves}")

    return '\n'.join(result_lines)

