def can_removed(a):
    n = len(a)
    if n < 2:
        return False
    x = a[0]
    for i in range(1, n):
        x = a[i] - x
        if x < 0:
            return False
    return x == 0

def solve(n, a):
    if can_removed(a):
        return "YES"

    for i in range(n - 1):
        b = a.copy()
        b[i], b[i + 1] = b[i + 1], b[i]
        if can_removed(b):
            return "YES"

    return "NO"

