MOD = 998244353

def mod_inv(n):
    return pow(n, MOD - 2, MOD)

def factorial(n):
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    return fact

def inv_factorial(n):
    fact = factorial(n)
    return mod_inv(fact)

def precompute_binomial(n):
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    return [fact[i] * mod_inv(fact[i]) % MOD for i in range(n + 1)]

