def solution(input_string):
    try:
        lines = input_string.strip().split('\n')
        if len(lines) < 3:
            return "0"
        s1 = lines[0]
        s2 = lines[1]
        virus = lines[2]

        n, m, v = len(s1), len(s2), len(virus)
        INF = -10**9

        # Build KMP failure function for the virus
        pi = [0] * v
        k = 0
        for i in range(1, v):
            while k > 0 and virus[k] != virus[i]:
                k = pi[k-1]
            if virus[k] == virus[i]:
                k += 1
            pi[i] = k

        # KMP transition: given state k (matched prefix length) and char c, return new state
        def kmp_next(k, c):
            while k > 0 and virus[k] != c:
                k = pi[k-1]
            if virus[k] == c:
                k += 1
            return k

        # dp[i][j][k] = max LCS length using s1[:i] and s2[:j] with virus match state k
        # Initialize with sentinel value
        dp = [[[INF] * v for _ in range(m + 1)] for _ in range(n + 1)]
        dp[0][0][0] = 0

        # direction[i][j][k] = track path for reconstruction: ('M', i, j) or ('S1', i, j) or ('S2', i, j)
        direction = [[[None] * v for _ in range(m + 1)] for _ in range(n + 1)]

        for i in range(n + 1):
            for j in range(m + 1):
                for k in range(v):
                    if dp[i][j][k] == INF:
                        continue

                    # Option 1: Match s1[i] with s2[j] (if they're equal)
                    if i < n and j < m and s1[i] == s2[j]:
                        c = s1[i]
                        new_k = kmp_next(k, c)
                        if new_k < v:  # Don't complete virus as substring
                            new_len = dp[i][j][k] + 1
                            if new_len > dp[i+1][j+1][new_k]:
                                dp[i+1][j+1][new_k] = new_len
                                direction[i+1][j+1][new_k] = ('M', i, j)

                    # Option 2: Skip s1[i]
                    if i < n:
                        if dp[i][j][k] > dp[i+1][j][k]:
                            dp[i+1][j][k] = dp[i][j][k]
                            direction[i+1][j][k] = ('S1', i, j)

                    # Option 3: Skip s2[j]
                    if j < m:
                        if dp[i][j][k] > dp[i][j+1][k]:
                            dp[i][j+1][k] = dp[i][j][k]
                            direction[i][j+1][k] = ('S2', i, j)

        # Find best final state
        max_len = 0
        best_k = 0
        for k in range(v):
            if dp[n][m][k] > max_len:
                max_len = dp[n][m][k]
                best_k = k

        if max_len == 0:
            return "0"

        # Reconstruct the LCS
        res = []
        i, j, k = n, m, best_k
        while i > 0 and j > 0:
            d = direction[i][j][k]
            if d is None:
                i, j = i - 1, j - 1
                continue

            action, prev_i, prev_j = d

            if action == 'M':
                res.append(s1[prev_i])

            i, j = prev_i, prev_j

        return ''.join(reversed(res))
    except Exception:
        return "0"

