def solution(in_str):
    lines = in_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n, m, k = map(int, lines[0].split())

    if n == 1:
        if k == 0:
            return "0\n\n"
        return "-1\n"

    if m < n - 1:
        return "-1\n"

    edges = []
    capital_idx = set()
    for i in range(m):
        if i + 1 > len(lines):
            break
        u, v, w = map(int, lines[i + 1].split())
        edges.append((u, v, w, i + 1))
        if u == 1 or v == 1:
            capital_idx.add(i)

    def kruskal_with_penalty(n, edges_list, lambda_val):
        modified_edges = []
        for i in range(len(edges_list)):
            weight = edges_list[i][2] + lambda_val if i in capital_idx else edges_list[i][2]
            modified_edges.append((weight, edges_list[i]))

        modified_edges.sort(key=lambda x: (x[0], x[1], x[2]))

        parent = list(range(n + 1))
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        selected = []
        capital_count = 0

        for weight, (u, v, w, idx) in modified_edges:
            root_u = find(u)
            root_v = find(v)
            if root_u != root_v:
                parent[root_u] = root_v
                selected.append(idx)
                if u == 1 or v == 1:
                    capital_count += 1

        # Union all edges to check connectivity
        parent = list(range(n + 1))
        for (u, v, w, _), i in [(e, i) for i, e in enumerate(edges_list)]:
            root_u, root_v = find(parent, u), find(parent, v)
            if root_u != root_v:
                parent[root_u] = root_v

        roots = set(find(parent, i) for i in range(1, n + 1))
        is_connected = len(roots) == 1

        return is_connected, capital_count, selected

    # Try multiple penalty values
    penalites = sorted(set([0] + [-idx * 1000000 for idx in range(1, 20)]))
    ans = None

    for p in penalites:
        is_conn, count, sel = kruskal_with_penalty(n, edges, p)
        if is_conn and count == k:
            ans = sel
            break

    if ans is None:
        # Fine-grained search
        low, high = -200000, 200000
        for _ in range(50):
            mid = (low + high) // 2
            is_conn, count, sel = kruskal_with_penalty(n, edges, mid)
            if count == k:
                if is_conn:
                    ans = sel
                    break
            elif count < k:
                high = mid
            else:
                low = mid

    if ans is None:
        return "-1\n"

    if sum(1 for i in edges if i[0] == 1 or i[1] == 1 for _, (_, _, _, i) in enumerate(edges)) != k:
        is_conn, count, sel = kruskal_with_penalty(n, edges, 0)
        if not is_conn or count != k:
            return "-1\n"
        ans = sel

    return f"{len(ans)}\n{' '.join(map(str, ans))}\n"

