from itertools import combinations

def cross_product(a, b, c):
    """Cross product of vectors (b-a) and (c-a)."""
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

def segments_intersect(p1, p2, p3, p4):
    """Check if segments p1-p2 and p3-p4 intersect at an internal point."""
    cp1 = cross_product(p1, p2, p3)
    cp2 = cross_product(p1, p2, p4)
    cp3 = cross_product(p3, p4, p1)
    cp4 = cross_product(p3, p4, p2)
    return (cp1 * cp2 < 0) and (cp3 * cp4 < 0)

def point_on_segment(p, a, b):
    """Check if point p is on segment ab (including endpoints)."""
    return cross_product(a, b, p) == 0

def triangles_disjoint(t1, t2):
    """Two triangles are disjoint if no edges cross and no point is inside/on boundary of other."""
    # Check if any point from tri1 is on the boundary of tri2
    for p in t1:
        for a, b in combinations(t2, 2):
            if point_on_segment(p, a, b):
                return False
    # Check if any point from tri2 is on the boundary of tri1
    for p in t2:
        for a, b in combinations(t1, 2):
            if point_on_segment(p, a, b):
                return False
    # Check if any edges intersect
    for a, b in combinations(t1, 2):
        for c, d in combinations(t2, 2):
            if segments_intersect(a, b, c, d):
                return False
    return True

