def solution(input_str):
    l, r = map(int, input_str.strip().split())

    if l > r:
        return "0\n"

    limit = isqrt(r)

    # Find primes up to sqrt(r) for sieving
    base_primes = []
    if limit >= 2:
        sieve = [True] * (limit + 1)
        sieve[0] = sieve[1] = False
        for i in range(2, limit + 1):
            if sieve[i]:
                base_primes.append(i)
                for j in range(i * i, limit + 1, i):
                    sieve[j] = False

    # Create boolean array for range [l, r]
    is_prime_range = [True] * (r - l + 1)

    # Mark 1 as composite if it's in range
    if l <= 1 and 1 <= r:
        is_prime_range[1 - l] = False

    # Sieve: mark composites in [l, r]
    for p in base_primes:
        # Find first multiple of p >= max(l, 2)
        start = p if p >= l else ((l + p - 1) // p) * p
        if start < 2:
            start = 2

        if start <= r:
            for i in range(start, r + 1, p):
                is_prime_range[i - l] = False

    # Count primes where p = 2 or p % 4 == 1
    count = 0
    for i in range(l, r + 1):
        if i <= 1:
            continue
        if i == 2:
            count += 1
        else:
            if is_prime_range[i - l] and i % 4 == 1:
                count += 1

    return str(count) + '\n'

