def solution(input_str):
    if not input_str.strip():
        return '0'

    n, p, l, r = map(int, input_str.split())

    # Precompute factorials
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % p

    def mod_inv(a, mod):
        return pow(a, mod - 2, mod)

    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        if r == 0 or r == n:
            return 1
        num = fact[n]
        den = (fact[r] * fact[n - r]) % p
        return (num * mod_inv(den, p)) % p

    total = 0

    for u in range(l, r + 1):
        s_start = abs(u)

        for s in range(s_start, n + 1):
            if (s - u) % 2 != 0:
                continue

            k = (u + s) // 2  # number of A's
            m = (s - u) // 2  # number of B's
            p_count = n - s   # number of C's

            # Number of valid A/B sequences with ballot constraint
            if m == 0:
                valid_ab = 1
            else:
                valid_ab = (nCr_mod(s, m) - nCr_mod(s, m - 1)) % p

            # Ways to choose positions for C's
            pos_c = nCr_mod(n, p_count)

            total = (total + pos_c * valid_ab) % p

    return str(total)

