class Solution:
    def __init__(self):
        self.active_pairs = {}

    def process_query(self, query_type, params):
        """Process a single query"""
        if query_type == 1:
            a, b = params
            self.active_pairs[len(self.active_pairs) + 1] = (a, b)
        elif query_type == 2:
            idx = params
            if idx in self.active_pairs:
