                points.append((x, y))

    from itertools import product

    max_score = -1
    best_towers = None

    # Try all possible configurations (n points with replacement)
    for config in product(range(len(points)), repeat=n):
        towers = [points[i] for i in config]

        # Calculate sum of squared pairwise distances
        score = 0
        for i in range(n):
            for j in range(i + 1, n):
                dx = towers[i][0] - towers[j][0]
                dy = towers[i][1] - towers[j][1]
                score += dx*dx + dy*dy

        if score > max_score:
            max_score = score
            best_towers = towers

    # Format output
