    """Convert string to binary, get reverse, get complement, get reverse of complement, return min"""
    # Already assume binary string with 0s and 1s
    rev = s[::-1]
    comp = ''.join(['1' if c == '0' else '0' for c in s])
    rev_comp = comp[::-1]
    return min([s, rev, comp, rev_comp])

