# solution.py

def solve(n, m, frogs):
    """
    Solve the frog game problem.

    Args:
        n: number of frogs
        m: number of cells on the board (cyclic, 1-indexed)
        frogs: list of (position, jump_length) for each frog (1-indexed)

    Returns:
        List of frog indices that remain on the board
    """
    # Store active frogs: frog_id -> (position, jump_length)
    active = {}
    for i in range(n):
        active[i + 1] = (frogs[i][0], frogs[i][1])

    # Set of active frog IDs
    active_ids = set(active.keys())

    # Convert position to 0-indexed for easier calculation
    # Position p means cell p (1-indexed), so we store p-1
    active_od = {}  # 0-indexed position

    for fid, (pos, jmp) in active.items():
        active_od[fid] = pos - 1

    def get_cyclic_pos(start, steps):
        """Calculate cyclic destination from start with given steps."""
        dest = (start + steps) % m
        return dest  # return 0-indexed

    def get_path_cells(start, steps):
        """Get all cells visited when jumping from start with given steps."""
        dest = get_cyclic_pos(start, steps)
        if steps <= 0:
            return []

        if start == dest:
            # Completed full cycle, will pass through all cells
            return list(range(m))

        path = []
        curr = start
        visited = set()
        step_count = 0

        # Collect cells until we reach destination
        while step_count < steps:
            path.append(curr)
            curr = (curr + 1) % m
            step_count += 1
            visited.add(curr)

        # Check if destination is in path
        path.append(dest)

        return path

    # For efficiency, instead of simulating step by step,
    # we calculate which frogs are knocked out in each turn

    frog_num = 1
    while active_od:
        if frog_num not in active_od:
            frog_num += 1
            continue

        pos, jmp = active_od[frog_num]

        if jmp <= 0:
            frog_num += 1
            continue

        # Calculate destination
        dest = (pos + jmp - 1) % m  # -1 for 0-indexed

        # Find all frogs on the path from pos to dest
        # Path includes cells from pos to dest, following the jump length

        # For efficiency on large boards, only check active frogs
        knocked_out = []

        # Case 1: path doesn't wrap around many times
        # hops = ceil(jmp / m), but we can optimize

        # Actually, let's think about this differently:
        # If jmp is small compared to m, we check cells near pos
        # If jmp is large, the frog might hit many frogs

        if jmp >= m:
            # Full cycle or more - will hit every cell
            # This means all other active frogs are knocked out
            keys_to_remove = []
            for fid in active_ids:
                if fid != frog_num:
                    keys_to_remove.append(fid)
            for fid in keys_to_remove:
                active_od.pop(fid)
                active_ids.remove(fid)
            jmp = 0

        else:
            # Find frogs on the path
            # Path starts at pos, goes to pos, pos+1, ..., pos+jmp-1 (mod m)
            path_frogs = []

            # Check if any active frog is on the path
            # For each active frog (except current), check if it's on path

            for fid in active_ids:
                if fid == frog_num:
                    continue

                fd_pos = active_od[fid][0]
                if pos <= fd_pos:
                    # fd_pos is ahead of or at pos
                    if fmap % m <= jmp - 1:
                        path_frogs.append(fid)
                else:
                    # fd_pos is behind pos, need to wrap around
                    if fd_pos + m <= pos + jmp - 1:
                        path_frogs.append(fid)

            # Update jump length
            new_jmp = jmp - len(path_frogs)
            # In this case, we update in place
            # But wait, the problem says ai is decreased by number of frogs knocked out
            # during this turn, and those frogs don't contribute to the count

            updated = False
            if new_jmp > 0 and path_frogs:
                # Frogs get knocked out
                gid_list = [fid for fid in path_frogs if fid in active_ids]
                for fid in gid_list:
                    del active_od[fid]
                    active_ids.remove(fid)
                active_od[frog_num] = (active_od[frog_num][0], new_jmp)
                updated = True

            if not updated:
                active_od[frog_num] = (active_od[frog_num][0], new_jmp)

        frog_num += 1

    return list(active_od.keys())


