def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0].strip():
        return "0\n"

    parts = list(map(int, lines[0].split()))
    if len(parts) < 3:
        return "0\n"
    N, M, K = parts[0], parts[1], parts[2]

    # Map (r, c, time) -> energy cost to kill transformer(s) at this position and time
    pos_time_cost = defaultdict(lambda: defaultdict(int))

    for i in range(1, K + 1):
        if i >= len(lines):
            break
        try:
            params = list(map(int, lines[i].split()))
            if len(params) < 5:
                continue
            x, y, d, t_start, e = params[0], params[1], params[2], params[3], params[4]

            # Build the 4-position cycle for this transformer
            cycle = [
                (x, y),
                (x + d, y - d),
                (x + d, y),
                (x, y + d)
            ]

            # Each position in the cycle appears every 4 time units after start
            for phase in range(4):
                px, py = cycle[phase]
                # Check if position is within bounds
                if 0 <= px < N and 0 <= py < M:
                    # Calculate the start time for this position in the cycle
                    pos_start_time = t_start + phase

                    # Record the energy cost at each occurrence of this position
                    arrival_time = pos_start_time
                    while arrival_time <= N + M:
                        pos_time_cost[(px, py)][arrival_time] += e
                        arrival_time += 4

        except Exception as ex:
            continue

    # For each cell (r, c), determine cost to pass through
    # Blackout reaches (r,c) at time t = r + c
    cell_cost = {}  # (r,c) -> cost to pass through

    for r in range(N):
        for c in range(M):
            t = r + c
            cost_at_cell = 0
            if (r, c) in pos_time_cost and t in pos_time_cost[(r, c)]:
                cost_at_cell = pos_time_cost[(r, c)][t]
            cell_cost[(r, c)] = cost_at_cell

    # DP: minimum energy to reach each cell from (0,0)
    INF = float('inf')
    dp = [[INF] * M for _ in range(N)]

    # Starting position cost
    dp[0][0] = cell_cost.get((0, 0), 0)

    for r in range(N):
        for c in range(M):
            if r == 0 and c == 0:
                continue

            # Check costs from top (r-1,c) and left (r,c-1)
            prev_costs = []
            if r > 0:
                prev_costs.append(dp[r-1][c])
            if c > 0:
                prev_costs.append(dp[r][c-1])

            if prev_costs:
                dp[r][c] = min(prev_costs) + cell_cost.get((r, c), 0)

    result = dp[N-1][M-1]
    return str(result) if result != INF else "0\n"

