    """
    Determine if m roads can be built on a ring of n cities without intersections.
    Roads can be placed inside (i) or outside (o) the ring.
    Two roads cross if their endpoints interleave when traveling around the ring.
    Crossing roads must be placed on opposite sides.
    This becomes a 2-coloring problem on the crossing graph.
    """

    def check_crossing(a1, b1, a2, b2, n):
        """Check if two roads (a1,b1) and (a2,b2) cross on the ring."""
        # Normalize: ensure a < b for consistency
        if a1 > b1:
            a1, b1 = b1, a1
        if a2 > b2:
            a2, b2 = b2, a2

        # Check if x is in clockwise interval [l, r] around the circle
        def is_between(x, l, r):
            if l <= r:
                # Normal direction
                return l <= x <= r
            else:
                # Wraps around (l->l+n, r->r+n)
                return x >= l or x <= r

        # Check if endpoints of road2 are separated by road1's split
        a2_in_road1 = is_between(a2, a1, b1)
        b2_in_road1 = is_between(b2, a1, b1)

        # Check if endpoints of road1 are separated by road2's split
        a1_in_road2 = is_between(a1, a2, b2)
        b1_in_road2 = is_between(b1, a2, b2)

        # Cross if endpoints interleave (exactly one in each interval)
        return (a2_in_road1 != b2_in_road1) and (a1_in_road2 != b1_in_road2)

    # Parse input
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())
    roads = []
    for i in range(m):
        a, b = map(int, lines[1 + i].split())
        roads.append((a, b))

    # Build adjacency graph of crossing roads
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if check_crossing(roads[i][0], roads[i][1], 
                             roads[j][0], roads[j][1], n):
                adj[i].append(j)
                adj[j].append(i)

    # 2-color the graph (bipartite check)
    colors = [-1] * m  # -1: uncolored, 0: inside, 1: outside

    def dfs(u, c):
        colors[u] = c
        for v in adj[u]:
            if colors[v] == -1:
                if not dfs(v, 1 - c):
                    return False
            elif colors[v] == c:
                return False  # Conflict, not bipartite
        return True

    possible = True
    for i in range(m):
        if colors[i] == -1:
            if not dfs(i, 0):
                possible = False
                break

    if not possible:
        return "Impossible"

    # Map colors to 'i' (inside) and 'o' (outside)
    return ''.join('i' if colors[i] == 0 else 'o' for i in range(m))


