import random

def solve_match(a, b, match_idx):
    # Possible match outcomes (A_wins, B_wins, is_maximized_for_A)
    # Ordered by A_wins - B_wins
    outcomes = [
        (3, 0, True),   # 3:0 - A wins all 3
        (3, 1, True),   # 3:1 - A wins 3 sets
        (3, 2, True),   # 3:2 - A wins 3 sets  
        (0, 3, True),   # 0:3 - B wins all 3
        (1, 3, True),   # 1:3 - B wins 3 sets
        (2, 3, True),   # 2:3 - B wins 3 sets
    ]

    # Also with shuffle for randomized scoring distribution
    random.seed(match_idx * 12345)

    for A_wins, B_wins in outcomes:
        num_sets = A_wins + B_wins
        valid_seq = find_valid_sequence(a, b, A_wins, B_wins, num_sets)
        if valid_seq:
            return f"{A_wins}:{B_wins}\n" + ' '.join(
                f"{sa}:{sb}" for sa, sb in valid_seq
            ) + ' '

    return "Impossible"

def valid_set_score(points_a, points_b, set_num):
    """Check if a set score is valid and return winner (1=A, 2=B, 0=invalid)"""
    if set_num <= 4:  # Regular set
        if points_a >= 25 and points_a >= points_b + 2 and points_b <= 24:
            return 1
        if points_b >= 25 and points_b >= points_a + 2 and points_a <= 24:
            return 2
        # Deuce scenarios (24-24 leading to 26-24, etc.)
        if points_a >= 26 and points_a - points_b == 2 and points_b >= 24:
            return 1
        if points_b >= 26 and points_b - points_a == 2 and points_a >= 24:
