    return 0

def min_a_victory_wins(winner, loser):
    """Minimum points for winner to win, maximum for loser"""
    if winner == 'A':
        base = 25 if loser in [1, 2, 3] else 15
        return base, base  # loser gets 0, 14, or more
    return 25, 24  # reversed

def find_valid_sequence(a_total, b_total, A_wins, B_wins, num_sets):
    """Try to find valid set scores that sum to a_total and b_total"""

    # Strategy: greedily assign set scores
    set_sequence = [None] * num_sets
    remaining_a, remaining_b = a_total, b_total
    A_win_count, B_win_count = 0, 0

    for i in range(num_sets):
        # Determine who should win based on target match score
        if i < A_wins:
            winner = 'A'
        elif i < A_wins + B_wins - 1:  # Skip last one if needed
            winner = 'B'
        else:
            winner = 'A'

        # Constraint: match score must end correctly
        if A_win_count + 1 == target_A_wins and B_win_count == target_B_wins:
            break

        # Generate possible scores for this set
        if A_wins > B_wins:
            # A should win more sets
            possible = generate_scores_for_winner('A', remaining_a, remaining_b, i, num_sets, A_wins, B_wins)
        else:
            possible = generate_scores_for_winner('B', remaining_a, remaining_b, i, num_sets, A_wins, B_wins)

        for sa, sb in possible:
            if valid_set_score(sa, sb, i + 1):
                new_rem_a, new_rem_b = remaining_a - sa, remaining_b - sb
                if new_rem_a >= 0 and new_rem_b >= 0:
                    if new_rem_a + new_rem_b == 0:
                        # Perfect match!
                        return set_sequence
                    # Try continuing
                    set_sequence[i] = (sa, sb)
                    A_win_count = A_win_count + (1 if sa >= sb else 0)
                    B_win_count = B_win_count + (1 if sb >= sa else 0)
                    break

    # Check final conditions
    if set_sequence and sum(s[0] for s in set_sequence) == a_total and sum(s[1] for s in set_sequence) == b_total:
        return set_sequence

    return None

def generate_scores_for_winner(winner, rem_a, rem_b, set_idx, num_sets, A_wins, B_wins):
    """Generate possible scores where the specified team wins"""
    possibilities = []

    if winner == 'A':
        # Try A scores from 25 up to reasonable limits
        base = 25 if set_idx < 4 else 15
        for a_cand in range(base, min(rem_a + 1, base + 10)):
            constraint_b = min(a_cand - 2, 24 if set_idx < 4 else 14)
            max_b = min(rem_b, constraint_b)
            for b_cand in range(max(0, 0), max_b + 1):
                if a_cand - b_cand >= 2 and (set_idx < 4 or b_cand <= 14):
                    possibilities.append((a_cand, b_cand))
                    break  # Just take first valid
    else:
        # Try B scores
