def solution(input_str):
    n, k = map(int, input_str.split())

    if k > n:
        return "0\n"

    if k == 1:
        return f"{n}\n"

    # Precompute factorials for combinations
    fact = [1] * (n + 1)
    invFact = [1] * (n + 1)

    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invFact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        invFact[i] = invFact[i + 1] * (i + 1) % MOD

    def C(n_comb, k_comb):
        if k_comb < 0 or k_comb > n_comb:
            return 0
        return fact[n_comb] * invFact[k_comb] % MOD * invFact[n_comb - k_comb] % MOD

    ans = 0
    l = 1
    while l <= n:
        v = n // l
        r = n // v
        if v >= k:
            term = C(v - 1, k - 1)
            if term:
                ans = (ans + (r - l + 1) * term) % MOD
        l = r + 1

    return f"{ans}\n"

