            for t_cand in [start_t, end_t]:
                if t_cand < 0:
                    t_cand = 0
                s_pos = snitch_at_time(t_cand)
                harry_arrival = dist(P_start, s_pos) / vp_f
                if harry_arrival <= t_cand + 1e-9:
                    if t_cand < min_correct or (min_correct is None):
                        min_correct = t_cand
                        best_pos = s_pos

        # Binary search for minimum between entry and end
        min_cand = None
        if min_correct is not None:
            min_cand = min_correct

        l, r = 0, prev_dist / vs + seg_len / vs
        for _ in range(80):
            mid = (l + r) / 2
            if mid < 0:
                mid = 1e-9 if mid == 0 else mid
            s_pos = snitch_at_time(mid)
            d_req = dist(P_start, s_pos)
            if d_req / vp_f <= mid + 1e-9:
                if mid < min_cand:
                    min_cand = mid
                    best_pos = s_pos
                r = mid
            else:
                l = mid

        if min_cand is not None and min_cand < min_t:
            min_t = min_cand
            best_pos = best_pos

    if best_pos:
        return "YES\n" + str("{:.10f}".format(min_t)) + "\n" + " ".join("{:.10f}".format(best_pos[i]) for i in range(3)) + "\n"
    else:
        return "NO\n"

def dist(p1, p2):
    return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2)

def snitch_at_time(t, points, vs):
    cumd = 0
    for seg_idx in range(len(points) - 1):
        slen = dist(points[seg_idx], points[seg_idx + 1])
        if slen == 0:
            continue
        seg_time = slen / vs
        if cumd + slen >= t * vs:
            rem = max(0, t * vs - cumd)
            frac = rem / slen
            return (points[seg_idx][0] + frac * (points[seg_idx+1][0] - points[seg_idx][0]),
                    points[seg_idx][1] + frac * (points[seg_idx+1][1] - points[seg_idx][1]),
                    points[seg_idx][2] + frac * (points[seg_idx+1][2] - points[seg_idx][2]))
        cumd += slen
    return (points[-1][0], points[-1][1], points[-1][2])

def can_catch(P_start, points, vp, vs, seg_idx, t, prev_dist):
    s_pos = snitch_at_time(t, points, vs)
    d_req = dist(P_start, s_pos)
    harry_arrival = d_req / vp
    return harry_arrival <= t + 1e-9

