    def dist(p1, p2):
        return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2)

    def get_snitch_pos(t):
        d_req = 0
        for seg_idx in range(n - 1):
            slen = dist(points[seg_idx], points[seg_idx + 1])
            if t * vs >= d_req + slen:
                d_req += slen
            else:
                frac = (t * vs - d_req) / slen
                return (points[seg_idx][0] + frac * (points[seg_idx+1][0] - points[seg_idx][0]),
                        points[seg_idx][1] + frac * (points[seg_idx+1][1] - points[seg_idx][1]),
                        points[seg_idx][2] + frac * (points[seg_idx+1][2] - points[seg_idx][2]))
        return (points[n-1][0], points[n-1][1], points[n-1][2])

    if vp < vs:
        return "NO\n"

    vp_f, vs_f = float(vp), float(vs)
    min_t = float('inf')
    best_pos = None

    # Check each segment
    for seg_idx in range(n - 1):
        prev_d = 0
        for i in range(seg_idx):
            prev_d += dist(points[i], points[seg_idx])

        seg_len = dist(points[seg_idx], points[seg_idx + 1])
        seg_start_t = prev_d / vs_f
        seg_len_time = seg_len / vs_f

        def check_t_and_update(t):
            nonlocal min_t, best_pos
            if t <= 0:
                return False
            s = get_snitch_pos(t)
            d_rech = dist(P_start, s)
            if d_rech / vp_f <= t + 1e-9:
                if t < min_t - 1e-8:
                    min_t = t
                    best_pos = s
                return True
            return False

        # Check entry point
        t_check = seg_start_t
        if t_check <= 0:
            t_check = 0.001
        check_t_and_update(t_check)

        # Binary search
        l, r = t_check, seg_start_t + seg_len_time
        for _ in range(80):
            if r - l < 1e-14:
                break
            mid = (l + r) / 2
            if check_t_and_update(mid):
                r = mid
            else:
                l = mid

        if best_pos:
            break

    if best_pos:
        return "YES\n" + str("{:.10f}".format(min_t)) + "\n" + " ".join("{:.10f}".format(best_pos[i]) for i in range(3)) + "\n"
    return "NO\n"

def solution(input_str):
    n, k, l_val = map(int, input_str.strip().split())
    MOD = 998244353

    # Precompute factorials
    MAX = 2 * n + 10
    fact = [1] * MAX
    for i in range(1, MAX):
        fact[i] = fact[i - 1] * i % MOD

    # Precompute inverse factorials
    invFact = [1] * MAX
    invFact[MAX - 1] = pow(fact[MAX - 1], MOD - 2, MOD)
    for i in range(MAX - 2, -1, -1):
        invFact[i] = invFact[i + 1] * (i + 1) % MOD

    def nCr(n_cnt, r_cnt):
        if r_cnt < 0 or r_cnt > n_cnt:
            return 0
        return fact[n_cnt] * invFact[r_cnt] % MOD * invFact[n_cnt - r_cnt] % MOD

    def modPow(a, b):
        return pow(a, b, MOD)

    # Integral of (t(1-t))^m from 0 to 1 is m! * m! / (2*m + 1)!
    def integral_contribution(m):
        num = fact[m] * fact[m] % MOD
        return num * pow(fact[2 * m + 1], MOD - 2, MOD) % MOD

    result = 0

    # Sum over j from k to n
    for j in range(k, n + 1):
        # Contribution: C(n,j) * 2^j * sum_{i=0}^{n-j} C(n-j,i) * (-1)^i * integral((j+i))
        binom_coef = nCr(n, j)

        for i in range(n - j + 1):
            inner_coefs = nCr(n - j, i)

            # Apply sign based on i
            if i % 2 == 1:
                inner_coefs = (MOD - inner_coefs) % MOD

            exponent = j + i
            int_val = integral_contribution(exponent)

            term = binom_coef * inner_coefs % MOD * int_val % MOD
            result = (result + term) % MOD

    # Multiply by l
    result = result * l_val % MOD
    return str(result)


